   165	      // untouched rather than closing something it did not open.
   166	      const depth = stack.findIndex((frame) => frame.tag === tag);
   167	      if (depth <= 0) continue;
   168	      while (stack.length > depth) closeTop();
   169	      continue;
   170	    }
   171	
   172	    if (VOID_TAGS.has(tag)) {
