import React from 'react';
import { createRoot } from 'react-dom/client';
import { ChakraProvider, VStack, Skeleton, Heading, Box } from '@chakra-ui/react';
import theme from 'app/theme';
import { ZimmTokensGlobal } from 'app/theme/zimmTokensGlobal';
import { ZimmProductContent } from 'app/components/ui-kits/molecules/zimmProductContent';
import { ZimmProductMeta } from 'app/components/ui-kits/molecules/zimmProductMeta';
import { selectPdpProductInfo } from 'app/pages/product-detail/productInfo';

/* ---------------------------------------------------------------------------
 * Verbatim reproduction of pages/product-detail/index.tsx:730-779
 * (renderStaticProductHeader) and of product-view/index.tsx:193-225
 * (the base private ProductViewHeader), so the two can be measured side by side.
 * ------------------------------------------------------------------------- */

const formatPrice = (amount: number, currency: string) =>
  new Intl.NumberFormat('en-AU', { style: 'currency', currency }).format(amount);

type HeaderProps = {
  name?: string;
  product?: any;
  priceData?: any;
  currency?: string;
  category?: any[];
  isProductPartOfBundle?: boolean;
};

// ---- OURS (pdp index.tsx:730-779), breadcrumb omitted (base-identical, needs router) ----
const ZimmHeader = ({ name, product: headerProduct, priceData, currency, isProductPartOfBundle }: HeaderProps) => {
  const info = selectPdpProductInfo(headerProduct ?? { name }, priceData, currency ?? '', formatPrice);
  return (
    <VStack mr={4} spacing={2} align="flex-start" marginBottom={[4, 4, 4, 0, 0]}>
      <Skeleton isLoaded={Boolean(info)} minHeight="var(--zimm-font-lineheight-2xs)" data-probe="zimm-name-skeleton">
        {info && (
          <ZimmProductContent
            name={info.name}
            headingLevel="h2"
            price={isProductPartOfBundle ? undefined : info.price}
            description={info.description}
          />
        )}
      </Skeleton>
      {!isProductPartOfBundle && (
        <Skeleton isLoaded={Boolean(headerProduct)} data-probe="zimm-promo-skeleton">
          {headerProduct?.productPromotions && <Box data-probe="promo">PROMO</Box>}
        </Skeleton>
      )}
    </VStack>
  );
};

// ---- BASE (product-view/index.tsx:193-225), breadcrumb + DisplayPrice stubbed ----
const BaseHeader = ({ name, product, priceData, isProductPartOfBundle }: HeaderProps) => (
  <VStack mr={4} spacing={2} align="flex-start" marginBottom={[4, 4, 4, 0, 0]}>
    <Skeleton isLoaded={name} data-probe="base-name-skeleton">
      <Heading fontSize="2xl" data-probe="base-title">{`${name}`}</Heading>
    </Skeleton>
    {!isProductPartOfBundle && (
      <>
        <Skeleton isLoaded={priceData?.currentPrice} data-probe="base-price-skeleton">
          {priceData?.currentPrice && <Box data-probe="base-price">$1,234.00</Box>}
        </Skeleton>
        <Skeleton isLoaded={product} data-probe="base-promo-skeleton">
          {product?.productPromotions && <Box data-probe="promo">PROMO</Box>}
        </Skeleton>
      </>
    )}
  </VStack>
);

/* ------------------------------- fixtures -------------------------------- */

const LOADED_PRODUCT = {
  id: '8637DS241-BLK-6',
  name: 'Ravello Ruffled Linen Midi Dress',
  longDescription:
    '<p>Crafted in Italy from a lightweight linen blend, the Ravello dress is cut to a relaxed midi silhouette with a tiered ruffled hem.</p>',
  master: { masterId: '8637DS241' },
};
const PRODUCT_WITH_MODELFIT = {
  ...LOADED_PRODUCT,
  c_modelFit: '<p>Model is 178cm / 5’9” and wears a size 0.</p>',
};
const PRICE = { currentPrice: 1250 };

/* --------------------------- scenario harness ---------------------------- */

const COL_WIDTH = 218; // the DS info-column width the D17 comment cites

const Scenario = ({ id, label, children }: any) => (
  <div data-scenario={id} style={{ width: COL_WIDTH, border: '1px solid #ccc', marginBottom: 24 }}>
    <div style={{ font: '10px monospace', background: '#eee' }}>{label}</div>
    {children}
  </div>
);

// Stub standing in for <ProductView/> + <InformationAccordion/>, so the
// accordions -> meta-block hop can be measured with no wrapper of my own.
const AccordionStub = () => (
  <div data-probe="accordion" style={{ height: 40, background: '#f6f6f6' }}>accordions</div>
);

const App = () => (
  <ChakraProvider theme={theme}>
    <ZimmTokensGlobal />

    <Scenario id="s1-loading" label="S1 header: loading (product undefined)">
      <ZimmHeader name={undefined} product={undefined} priceData={undefined} currency="AUD" />
    </Scenario>

    <Scenario id="s2-loaded" label="S2 header: loaded">
      <ZimmHeader name={LOADED_PRODUCT.name} product={LOADED_PRODUCT} priceData={PRICE} currency="AUD" />
    </Scenario>

    <Scenario id="s3-bundle" label="S3 header: loaded, isProductPartOfBundle">
      <ZimmHeader
        name={LOADED_PRODUCT.name}
        product={LOADED_PRODUCT}
        priceData={PRICE}
        currency="AUD"
        isProductPartOfBundle
      />
    </Scenario>

    <Scenario id="s4-nodesc" label="S4 header: loaded, no description, no price">
      <ZimmHeader name={LOADED_PRODUCT.name} product={{ ...LOADED_PRODUCT, longDescription: undefined }} priceData={undefined} currency="AUD" />
    </Scenario>

    <Scenario id="b1-loading" label="B1 BASE header: loading">
      <BaseHeader name={undefined} product={undefined} priceData={undefined} />
    </Scenario>

    <Scenario id="b2-loaded" label="B2 BASE header: loaded">
      <BaseHeader name={LOADED_PRODUCT.name} product={LOADED_PRODUCT} priceData={PRICE} />
    </Scenario>

    <Scenario id="m1-styleonly" label="M1 meta: styleCode only (today's catalogue)">
      <AccordionStub />
      <ZimmProductMeta
        modelInfo={selectPdpProductInfo(LOADED_PRODUCT, null, 'AUD', formatPrice)?.modelInfo}
        styleCode={selectPdpProductInfo(LOADED_PRODUCT, null, 'AUD', formatPrice)?.styleCode}
      />
    </Scenario>

    <Scenario id="m2-both" label="M2 meta: model line + styleCode">
      <AccordionStub />
      <ZimmProductMeta
        modelInfo={selectPdpProductInfo(PRODUCT_WITH_MODELFIT, null, 'AUD', formatPrice)?.modelInfo}
        styleCode={selectPdpProductInfo(PRODUCT_WITH_MODELFIT, null, 'AUD', formatPrice)?.styleCode}
      />
    </Scenario>

    <Scenario id="m3-loading" label="M3 meta: loading (product undefined)">
      <AccordionStub />
      <ZimmProductMeta
        modelInfo={selectPdpProductInfo(undefined, null, '', formatPrice)?.modelInfo}
        styleCode={selectPdpProductInfo(undefined, null, '', formatPrice)?.styleCode}
      />
    </Scenario>

    <Scenario id="m4-blankrich" label="M4 meta: c_modelFit = '<p></p>', no styleCode">
      <AccordionStub />
      <ZimmProductMeta modelInfo="<p></p>" styleCode={undefined} />
    </Scenario>
  </ChakraProvider>
);

createRoot(document.getElementById('root')!).render(<App />);
EOF
