const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1440, height: 2400 } });
const errors = [];
page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });
page.on('pageerror', (e) => errors.push('PAGEERROR: ' + e.message));
await page.goto('http://localhost:5599/', { waitUntil: 'networkidle' });
await page.waitForSelector('[data-scenario="m2-both"]', { timeout: 15000 });
await page.waitForTimeout(500);

const out = await page.evaluate(() => {
  const r = (el) => { const b = el.getBoundingClientRect(); return { top: +b.top.toFixed(2), bottom: +b.bottom.toFixed(2), h: +b.height.toFixed(2), w: +b.width.toFixed(2) }; };
  const res = {};
  for (const sc of document.querySelectorAll('[data-scenario]')) {
    const id = sc.getAttribute('data-scenario');
    const scTop = sc.getBoundingClientRect().top;
    const rel = (el) => { const b = el.getBoundingClientRect(); return { top: +(b.top - scTop).toFixed(2), bottom: +(b.bottom - scTop).toFixed(2), h: +b.height.toFixed(2), w: +b.width.toFixed(2) }; };
    const entry = { scenarioHeight: +sc.getBoundingClientRect().height.toFixed(2), nodes: {} };
    const sel = {
      nameSkeleton: '[data-probe="zimm-name-skeleton"]',
      promoSkeleton: '[data-probe="zimm-promo-skeleton"]',
      baseNameSkeleton: '[data-probe="base-name-skeleton"]',
      basePriceSkeleton: '[data-probe="base-price-skeleton"]',
      basePromoSkeleton: '[data-probe="base-promo-skeleton"]',
      baseTitle: '[data-probe="base-title"]',
      content: '[data-testid="product-content"]',
      productName: '[data-testid="product-name"]',
      productPrice: '[data-testid="product-price"]',
      productDescription: '[data-testid="product-description"]',
      accordion: '[data-probe="accordion"]',
      meta: '[data-testid="product-meta"]',
      modelInfo: '[data-testid="product-model-info"]',
      styleCode: '[data-testid="product-style-code"]',
    };
    for (const [k, s] of Object.entries(sel)) {
      const el = sc.querySelector(s);
      entry.nodes[k] = el ? rel(el) : null;
    }
    // computed styles that matter
    const meta = sc.querySelector('[data-testid="product-meta"]');
    if (meta) {
      const cs = getComputedStyle(meta);
      entry.metaComputed = { paddingTop: cs.paddingTop, rowGap: cs.rowGap, display: cs.display, flexDirection: cs.flexDirection };
    }
    const nameSk = sc.querySelector('[data-probe="zimm-name-skeleton"]');
    if (nameSk) {
      const cs = getComputedStyle(nameSk);
      entry.nameSkeletonComputed = { minHeight: cs.minHeight, height: cs.height, childCount: nameSk.children.length };
    }
    const baseSk = sc.querySelector('[data-probe="base-name-skeleton"]');
    if (baseSk) {
      const cs = getComputedStyle(baseSk);
      entry.baseNameSkeletonComputed = { minHeight: cs.minHeight, height: cs.height, text: baseSk.textContent };
    }
    const content = sc.querySelector('[data-testid="product-content"]');
    if (content) {
      const cs = getComputedStyle(content);
      entry.contentComputed = { rowGap: cs.rowGap, display: cs.display };
    }
    const pn = sc.querySelector('[data-testid="product-name"]');
    if (pn) { const cs = getComputedStyle(pn); entry.nameComputed = { fontSize: cs.fontSize, lineHeight: cs.lineHeight, tag: pn.tagName, text: pn.textContent }; }
    res[id] = entry;
  }
  res.__rootVar = getComputedStyle(document.documentElement).getPropertyValue('--zimm-font-lineheight-2xs');
  res.__scaleL = getComputedStyle(document.documentElement).getPropertyValue('--zimm-scale-l');
  return res;
});

console.log(JSON.stringify({ errors, out }, null, 2));
await page.screenshot({ path: '/tmp/pdpprobe/probe.png', fullPage: true });
