s=open(p).read()
s = s.replace(
"""import { ChakraProvider, VStack, Skeleton, Heading, Box } from '@chakra-ui/react';
import theme from 'app/theme';
import { ZimmTokensGlobal } from 'app/theme/zimmTokensGlobal';""",
"""import { ChakraProvider, VStack, Skeleton, Heading, Box, extendTheme } from '@chakra-ui/react';
import { borderWidths, breakpoints, colors, fonts, spacing, textStyles } from 'app/theme/foundation';
import { components } from 'app/theme/components';
import { globalStyles } from 'app/theme/globalStyles';
import { ZimmTokensGlobal } from 'app/theme/zimmTokensGlobal';

/*
 * Probe theme. Composed exactly as overrides/app/theme/index.ts composes it, minus the
 * `@salesforce/retail-react-app/app/theme` base (its .js modules cannot be parsed by this
 * throwaway Vite setup). The only base contribution relevant to these measurements is the
 * base Skeleton recipe, re-declared verbatim below from
 * node_modules/@salesforce/retail-react-app/app/theme/components/base/skeleton.js — it
 * carries no height/width, so it is layout-neutral either way.
 */
const theme = extendTheme({
  borderWidths,
  breakpoints,
  colors,
  fonts,
  space: spacing,
  textStyles,
  components: { ...components, Skeleton: { baseStyle: { borderRadius: 'base', opacity: 0.3 } } },
  styles: { global: globalStyles },
});""")
open(p,'w').write(s)
print('patched')
