import React from 'react';
import { createRoot } from 'react-dom/client';
import {
  ChakraProvider, extendTheme, Stack, Box, Flex, VStack, Skeleton,
} from '@chakra-ui/react';
import { borderWidths, breakpoints, colors, fonts, spacing, textStyles } from 'app/theme/foundation';
import { components } from 'app/theme/components';
import { globalStyles } from 'app/theme/globalStyles';
import { ZimmTokensGlobal } from 'app/theme/zimmTokensGlobal';
import { ZimmProductMeta } from 'app/components/ui-kits/molecules/zimmProductMeta';

const theme = extendTheme({
  borderWidths, breakpoints, colors, fonts, space: spacing, textStyles,
  components: { ...components, Skeleton: { baseStyle: { borderRadius: 'base', opacity: 0.3 } } },
  styles: { global: globalStyles },
});

/*
 * Faithful reproduction of the REAL ancestor chain around ZimmProductMeta:
 *   pages/product-detail/index.tsx:787  <Box layerStyle="page">      -> stubbed as a plain Box
 *   pages/product-detail/index.tsx:802  <Stack spacing={16}>         -> REAL
 *   pages/product-detail/index.tsx:894  <Fragment>                   -> no DOM
 *   pages/product-detail/index.tsx:895  <Island hydrateOn='visible'> -> no DOM (partialHydrationEnabled: false)
 *   pages/product-detail/index.tsx:896  <ProductView/>               -> stub: its root is <Flex direction="column"> (product-view:683)
 *   pages/product-detail/index.tsx:914  <InformationAccordion/>      -> stub: its root is <Stack direction="row" spacing={[0,0,0,16]}> (information-accordion.jsx:25)
 *   pages/product-detail/index.tsx:922  <ZimmProductMeta/>           -> REAL
 *   pages/product-detail/index.tsx:928  <Stack spacing={16}>         -> recommendations, stubbed
 */

const ProductViewStub = () => (
  <Flex direction="column" data-probe="productview" style={{ background: '#eef', height: 60 }}>
    ProductView (stub root = Flex, product-view/index.tsx:683)
  </Flex>
);

const AccordionStub = () => (
  <Stack direction="row" spacing={[0, 0, 0, 16]} data-probe="accordion-root">
    <Box maxWidth="896px" flex={[1, 1, 1, 5]} style={{ background: '#f6f6f6', height: 64 * 4 }}>
