  <Stack spacing={16} data-probe="recs">
    <Box style={{ background: '#efe', height: 40 }}>Recommendations</Box>
  </Stack>
);

const LOADED = { id: '8637DS241-BLK-6', name: 'X', master: { masterId: '8637DS241' } };

const Page = ({ modelInfo, styleCode, label, id }: any) => (
  <Box data-scenario={id} px={8} pt={8} pb={32} maxW="1440px" mx="auto" style={{ outline: '2px solid #900' }}>
