      <>
        <>
          <ProductViewStub />
          <AccordionStub />
          <ZimmProductMeta modelInfo={modelInfo} styleCode={styleCode} />
        </>
      </>
      <RecsStub />
    </Stack>
  </Box>
);

const App = () => (
  <ChakraProvider theme={theme}>
    <ZimmTokensGlobal />
    <Page id="c1" label="C1: real chain, styleCode only (today's catalogue)" modelInfo={undefined} styleCode={LOADED.master.masterId} />
    <Page id="c2" label="C2: real chain, model line + styleCode" modelInfo="<p>Model is 178cm and wears a size 0.</p>" styleCode={LOADED.master.masterId} />
