import { chromium } from '/Users/marcel.a.n.navarro/Dev/zimmermann-pwa/node_modules/playwright/index.mjs';
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1440, height: 3000 } });
const errs = [];
page.on('pageerror', (e) => errs.push('PAGEERROR: ' + e.message));
page.on('console', (m) => { if (m.type() === 'error') errs.push(m.text()); });
await page.goto('http://localhost:5599/chain.html', { waitUntil: 'networkidle' });
await page.waitForSelector('[data-scenario="c2"]');
await page.waitForTimeout(400);
const out = await page.evaluate(() => {
  const res = {};
  for (const sc of document.querySelectorAll('[data-scenario]')) {
    const id = sc.getAttribute('data-scenario');
    const g = (s) => sc.querySelector(s);
    const rect = (el) => el ? (({top,bottom,height}) => ({top:+top.toFixed(2),bottom:+bottom.toFixed(2),h:+height.toFixed(2)}))(el.getBoundingClientRect()) : null;
    const outer = g('[data-probe="outer-stack"]');
    const acc = g('[data-probe="accordion-root"]');
    const meta = g('[data-testid="product-meta"]');
    const model = g('[data-testid="product-model-info"]');
    const style = g('[data-testid="product-style-code"]');
    const recs = g('[data-probe="recs"]');
    res[id] = {
      outerStackComputed: outer ? (() => { const cs = getComputedStyle(outer); return { display: cs.display, flexDirection: cs.flexDirection, rowGap: cs.rowGap }; })() : null,
      outerStackDirectChildren: outer ? [...outer.children].map((c) => c.tagName + '.' + (c.getAttribute('data-probe') || c.getAttribute('data-testid') || '?')) : null,
      accordion: rect(acc),
      meta: rect(meta),
      modelInfo: rect(model),
      styleCode: rect(style),
      recs: rect(recs),
      metaComputed: meta ? (() => { const cs = getComputedStyle(meta); return { paddingTop: cs.paddingTop, rowGap: cs.rowGap }; })() : null,
      HOP_accordionBottom_to_firstMetaRow: (acc && (model || style)) ? +(((model || style).getBoundingClientRect().top) - acc.getBoundingClientRect().bottom).toFixed(2) : null,
      HOP_modelRow_to_styleRow: (model && style) ? +((style.getBoundingClientRect().top) - (model.getBoundingClientRect().bottom)).toFixed(2) : null,
      HOP_metaBottom_to_recsTop: (meta && recs) ? +((recs.getBoundingClientRect().top) - (meta.getBoundingClientRect().bottom)).toFixed(2) : null,
      HOP_accordionBottom_to_recsTop_whenMetaAbsent: (!meta && acc && recs) ? +((recs.getBoundingClientRect().top) - (acc.getBoundingClientRect().bottom)).toFixed(2) : null,
    };
  }
  return res;
});
console.log(JSON.stringify({ errs, out }, null, 2));
await page.screenshot({ path: '/private/tmp/pdpprobe/chain.png', fullPage: true });
await browser.close();
